# ANSI colors for the confirmation banner (bright yellow / bold). Disabled when
# stdout is not a TTY or NO_COLOR is set. On Windows, enable VT processing when possible.
_ANSI_RESET = "\033[0m"
_ANSI_WARN = "\033[1;93m"  # bold bright yellow
_ANSI_WARN_DIM = "\033[93m"  # bright yellow


def _warning_colors_enabled() -> bool:
    if os.environ.get("NO_COLOR"):
        return False
    if not getattr(sys.stdout, "isatty", lambda: False)():
        return False
    if sys.platform == "win32":
        try:
            import ctypes

            kernel32 = ctypes.windll.kernel32
            handle = kernel32.GetStdHandle(-11)  # STD_OUTPUT_HANDLE
            mode = ctypes.c_uint32()
            if not kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
                return False
            ENABLE_VIRTUAL_TERMINAL_PROCESSING = 0x0004
            if not (mode.value & ENABLE_VIRTUAL_TERMINAL_PROCESSING):
                if not kernel32.SetConsoleMode(
                    handle, mode.value | ENABLE_VIRTUAL_TERMINAL_PROCESSING
                ):
                    return False
        except Exception:
            return False
    return True


def _cwarn(text: str, *, bold: bool = False) -> str:
    if not _warning_colors_enabled():
        return text
    return f"{_ANSI_WARN if bold else _ANSI_WARN_DIM}{text}{_ANSI_RESET}"


def _confirm_warning(skip: bool = False) -> bool:
    'Show warning and ask for yes/no confirmation. Returns True if user agrees.'
    if skip:
        return True
    bar = "=" * 70
    print()
    print(_cwarn(bar, bold=True))
    print(_cwarn("WARNING", bold=True))
    print(_cwarn(bar, bold=True))
    print()
    print(_cwarn(WARNING_TEXT))
    print()
    while True:
        answer = input("Do you want to continue? (yes/no): ").strip().lower()
        if answer in ("yes", "y"):
            return True
        if answer in ("no", "n"):
            return False
        print("Please enter 'yes' or 'no'.")


