def _module_in_site_packages(site_packages: Path, import_name: str) -> bool:
    """True if import_name (e.g. "PyQt6.QtWebEngineWidgets") exists on disk there."""
    *parents, leaf = import_name.split(".")
    base = site_packages.joinpath(*parents)
    if (base / leaf).is_dir():
        return True
    for f in base.glob(leaf + ".*"):
        if f.suffix.lower() in (".py", ".pyd", ".so", ".pyc"):
            return True
    return False


def _check_missing_gui_deps(method: str = "pip") -> list[tuple[str, str, str]]:
    """Return entries from _GUI_DEPS that ofscraper's Python can't import.

    pipx and uv keep ofscraper in its own venv, so their packages are looked
    up in that venv's site-packages, not in the Python running this script
    (which made every GUI package look missing).
    """
    site_packages = _tool_site_packages(method)
    if site_packages is not None:
        return [
            dep for dep in _GUI_DEPS
            if not _module_in_site_packages(site_packages, dep[0])
        ]
    import importlib
    missing = []
    for import_name, pip_name, desc in _GUI_DEPS:
        try:
            importlib.import_module(import_name)
        except ImportError:
            missing.append((import_name, pip_name, desc))
    return missing


def _find_venv_pip(pkg_dir: "Path | None") -> "Path | None":
    """Walk from an ofscraper site-packages dir up to the venv root and find pip."""
    if not pkg_dir:
        return None
    sp_dir = pkg_dir.parent
    parent = sp_dir.parent
    venv_root = (
        parent.parent
        if parent.name.lower() in ("lib", "lib64") or parent.name.lower().startswith("python")
        else parent
    )
    if platform.system() == "Windows":
        for pip_name in ("pip.exe", "pip"):
            candidate = venv_root / "Scripts" / pip_name
            if candidate.exists():
                return candidate
    else:
        candidate = venv_root / "bin" / "pip"
        if candidate.exists():
            return candidate
    return None


def _install_gui_deps(method: str = "pip", *, force: bool = False) -> bool:
    """Install all required GUI dependencies using pip, pipx inject, or uv tool.

    Only installs packages that are not already importable, unless force=True
    (the --force option), which reinstalls every GUI package.  Returns True on
    success (or if nothing was missing).
    """
    if force:
        missing = list(_GUI_DEPS)
        print(f"Reinstalling all GUI dependencies (--force): {', '.join(d for _, _, d in missing)}")
    else:
        missing = _check_missing_gui_deps(method)
        if not missing:
            print("All GUI dependencies already installed.")
            return True

    missing_pip_names = [pip_name for _, pip_name, _ in missing]
    missing_descs = [desc for _, _, desc in missing]
    if not force:
        print(f"Missing GUI dependencies: {', '.join(missing_descs)}")

    run_cwd = os.path.expanduser("~") if method == "pipx" else None

    if method == "uv":
        # uv tool install reinstalls the tool; include ALL deps so none are dropped.
        _py_arg = _uv_python_arg()
        with_args = _uv_with_args(_gui_dep_names())
        if _py_arg:
            print("Installing GUI dependencies via uv (Python 3.12)...")
            print("(uv will download Python 3.12 automatically if not already installed)")
        else:
            print("Installing GUI dependencies via uv...")
        reinstall = ["--force", "--reinstall"] if force else []
        cmd = ["uv", "tool", "install"] + reinstall + ["ofscraper==3.14.7"] + with_args + _py_arg

        try:
            subprocess.run(cmd, check=True, capture_output=False)
            print("GUI dependencies installed successfully via uv.")
            return True
        except subprocess.CalledProcessError as e:
            print(f"ERROR: Failed to install GUI dependencies via uv (exit code {e.returncode}).")
            print("Make sure uv is installed and ofscraper was installed via 'uv tool install'.")
            return False
        except FileNotFoundError:
            print("ERROR: Could not find uv. Install it from: https://docs.astral.sh/uv/")
            return False

    elif method == "pipx":
        # Inject each missing package individually.
        print(f"Installing GUI dependencies via pipx inject: {', '.join(missing_pip_names)}")
        all_ok = True
        for pip_name in missing_pip_names:
            print(f"  pipx inject ofscraper {pip_name} ...")
            cmd = ["pipx", "inject"] + (["--force"] if force else []) + ["ofscraper", pip_name]
            try:
                subprocess.run(cmd, check=True, capture_output=False, cwd=run_cwd)
                print(f"  {pip_name} installed successfully.")
            except subprocess.CalledProcessError as e:
                print(f"  ERROR: Failed to inject {pip_name} (exit code {e.returncode}).")
                print(f"  Trying fallback: installing {pip_name} directly into the pipx venv...")
                venv_pip = _find_venv_pip(_find_pipx_ofscraper_pkg())
                if venv_pip:
                    try:
                        subprocess.run([str(venv_pip), "install"]
                                       + (["--force-reinstall"] if force else []) + [pip_name],
                                       check=True, capture_output=False)
                        print(f"  {pip_name} installed via venv pip fallback.")
                        continue
                    except subprocess.CalledProcessError:
                        pass
                print(f"  Could not install {pip_name}. Make sure pipx is installed.")
                all_ok = False
            except FileNotFoundError:
                _print_pipx_missing()
                return False
        return all_ok

    else:
        # pip — install all missing packages in a single command.
        print(f"Installing GUI dependencies via pip: {', '.join(missing_pip_names)}")
        cmd = ([sys.executable, "-m", "pip", "install"]
               + (["--force-reinstall"] if force else []) + missing_pip_names)
        try:
            subprocess.run(cmd, check=True, capture_output=False)
            print("GUI dependencies installed successfully.")
            return True
        except subprocess.CalledProcessError as e:
            print(f"ERROR: Failed to install GUI dependencies (exit code {e.returncode}).")
            print("You may need to run this script with elevated permissions.")
            return False
        except FileNotFoundError:
            print("ERROR: Could not find pip. Make sure Python and pip are installed.")
            return False


